"""Generate the standalone Korean tutorial; no network, API, or user data."""
from html import escape
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
REPO='https://github.com/PGH-snfl/embedded-vision'
INSTALL='curl -fsSL https://raw.githubusercontent.com/PGH-snfl/embedded-vision/main/install.sh | bash'

def command(title, code, ident):
    return f'''<div class="command"><div class="command-head"><b>{title}</b><div class="command-actions"><button data-action="reveal" aria-expanded="false" aria-controls="{ident}">명령어 보기</button><button data-action="copy" data-source="{ident}">명령어 복사</button></div></div><pre id="{ident}" hidden><code>{escape(code)}</code></pre></div>'''

def card(title, body, tag='사용 순서'):
    return f'<article class="spec"><div class="spec-head"><h3>{title}</h3><span class="badge">{tag}</span></div><div class="spec-body">{body}</div></article>'

def section(num, ident, title, intro, body):
    return f'<section id="{ident}"><div class="sec-head"><span class="sec-num">§{num:02}</span><h2>{title}</h2></div><p class="section-intro">{intro}</p>{body}</section>'

sections=[]
sections.append(section(1,'start','한 명령으로 시작','처음에는 설치를 진행하고, 준비가 끝나면 사진 입력 화면을 브라우저로 엽니다.',
 card('Ubuntu 22.04 · x86_64', '<p>데스크톱 Ubuntu 22.04의 64비트 Intel/AMD PC가 자동 설치 대상입니다. <b>curl과 인터넷 연결</b>이 필요합니다. 부족한 시스템 패키지는 sudo 비밀번호를 요청할 수 있습니다. Node.js·Python·편집기·UNO 컴파일러는 자동 준비합니다. KiCad는 기본 실행에 필요하지 않습니다.</p>'+command('다운로드 → 설치 → 화면 열기',INSTALL,'cmd-install')+'<p class="note">설치 위치: <code>~/embedded-vision</code>. 처음에는 대용량 의존성을 내려받고 빌드하므로 시간이 걸립니다. 이후에는 설치 결과를 재사용합니다. 터미널을 열어 둔 채 사용하고 <kbd>Ctrl</kbd> + <kbd>C</kbd>로 두 서버를 함께 종료하세요.</p><details><summary>실행 전에 스크립트 확인하기</summary><p>이 명령은 공개 저장소의 설치 스크립트를 실행합니다. 내용을 먼저 확인하려면 <a href="'+REPO+'/blob/main/install.sh">install.sh</a>, <a href="'+REPO+'/blob/main/scripts/bootstrap.sh">bootstrap.sh</a>를 읽으세요. 기존 설치가 있으면 덮어쓰거나 자동 업데이트하지 않고 다시 실행합니다.</p></details>','처음 한 번')+
 '<div class="grid">'+card('다시 실행',command('기존 설치 실행','cd "$HOME/embedded-vision" && bash start.sh','cmd-restart')+'<p>분석 화면 <a href="http://127.0.0.1:8766/">8766</a> · 편집기 <a href="http://127.0.0.1:8768/editor">8768</a>. 자동으로 열리지 않으면 주소를 클릭하세요.</p>')+card('직접 Git으로 받기',command('직접 설치','git clone '+REPO+'.git "$HOME/embedded-vision" && cd "$HOME/embedded-vision" && bash start.sh','cmd-clone')+'<p>이미 설치한 경로에 다시 clone하지 마세요. 실행 옵션은 <code>bash start.sh --help</code>에서 확인합니다.</p>')+'</div>'))
sections.append(section(2,'sample','API 키 없이 예제 실행','설치가 끝나면 먼저 내장 예제로 화면과 아두이노 실행을 확인하세요.',
 card('예제 둘러보기 → 보드별 공통 워크플로우 → Arduino UNO', '<ol><li>사진 입력 화면의 상단 <b>예제 둘러보기</b> 카드를 엽니다.</li><li><b>보드별 공통 워크플로우</b>를 선택합니다.</li><li>Arduino UNO 카드의 <b>회로·코드·시뮬레이터 열기</b>를 누릅니다.</li><li>편집기에서 회로 배선과 코드를 확인하고 <b>▶ 실행</b>합니다.</li><li>입력 부품을 조작하고 보드 출력 또는 동작 검사 결과가 바뀌는지 확인합니다.</li></ol><p class="note">이 경로는 내장 예제이므로 유료 사진 분석을 호출하지 않습니다. <b>실제 촬영 사진 분석</b> 버튼은 AI 분석을 시작하는 별도 기능입니다.</p>','무료 예제')+
 '<div class="preview"><div class="preview-board">Arduino UNO<div class="pins">D5　　GND　　5V</div></div><span class="wire">→</span><div class="preview-part">저항 → LED<br><small>배선·코드·출력 확인</small></div><span class="wire">→</span><div class="preview-result">▶ 시뮬레이션<br><small>직접 조작하고 확인</small></div></div>'))
sections.append(section(3,'key','사진 AI 분석 연결','사용자의 API 키와 해당 모델을 호출할 수 있는 계정·크레딧이 필요합니다.',
 card('키를 숨김 입력으로 저장',command('새 터미널에서 API 키 설정','cd "$HOME/embedded-vision" && bash configure_openai.sh','cmd-key')+'<ol><li>키를 붙여넣고 Enter를 누릅니다. 입력 문자는 화면에 표시되지 않습니다.</li><li><code>.runtime/openai-api-key</code>에 소유자만 읽도록 저장합니다.</li><li>웹 화면에서 상태를 갱신한 뒤 사진을 입력합니다. 키 설정만으로 사진을 자동 재분석하지 않습니다.</li></ol><p>이미 내보낸 <code>OPENAI_API_KEY</code> 환경변수가 있으면 그 값이 우선합니다. 별도 데이터 경로를 쓰면 키 설정 명령에도 같은 <code>EMBEDDED_VISION_DATA</code>를 지정하세요.</p><details><summary>키와 모델 접근이 실패할 때</summary><p>401: 키 확인. 403/404: 모델 접근 권한 또는 모델 ID 확인. 429: 사용 한도·잔액·요청 제한 확인. 현재 기본 모델 ID는 <code>gpt-6.1-sol</code>, 심화 모델은 <code>gpt-6-astra</code>입니다. 공개 API 계정에서 접근 가능하다고 보장하지 않습니다. 선택 가능한 모델은 <code>backend/planner/selection.py</code>와 서버 오류를 함께 확인하세요.</p></details>','AI 분석 필요') ))
sections.append(section(4,'input','사진·영상 입력과 구성품 확인','관측한 부품 목록을 먼저 만든 뒤, 그 목록을 근거로 시스템의 기능을 추론합니다.',
 '<div class="grid">'+card('① 입력 → ② 구성품 목록','<ol><li><b>사진 입력 · 자동 분석</b> 또는 <b>영상 입력</b>을 선택합니다.</li><li>사진은 PNG/JPEG, 최대 12MB입니다. 보드·센서·구조물 전체가 잘 보이는 이미지를 사용하세요.</li><li>왼쪽 번호에 따라 <b>구성품 목록</b>으로 이동합니다.</li><li>목록의 부품명·수량·위치와 실제 사진을 비교합니다. 필요한 근거·확대·검토 정보는 토글로 펼칩니다.</li></ol><p class="note">사진과 영상에서 추출한 프레임은 OpenAI API에 전송됩니다. 서버에 저장한 입력은 입력 삭제 기능으로 지울 수 있습니다.</p>')+card('확대·재검토가 하는 일','<p>전체 이미지에서 후보를 찾고 원본 영역을 잘라 확대합니다. 후보를 묶어 재검토하고 누락·중복을 점검합니다. 분석 단계마다 정해진 JSON 양식으로 결과를 받습니다.</p><p><b>처음 분석에는 대상 보드 정보를 강제로 주지 않습니다.</b> 관측 목록을 확정한 다음, 설계 단계에서 보드별 핀·전압·언어 규칙을 적용합니다.</p><p>각 단계의 시간·오류·근거를 확인할 수 있습니다. 확대해도 사진에 없던 내부가 관측 사실이 되지는 않습니다.</p>')+'</div>'))
sections.append(section(5,'design','기능·부품 보완과 시스템 데이터시트','원본 배선을 그대로 복제하기보다 같은 기능을 수행하는 새 회로를 구체적으로 설계합니다.',
 card('③ 기능·부품 보완 → 데이터시트 → 설계 목표','<ol><li>관측 부품을 바탕으로 나온 기능 후보와 가장 가능성이 높은 후보를 확인합니다.</li><li>실행에 필요한데 사진에서 보이지 않는 부품은 새 설계의 추가 부품으로 선정합니다.</li><li>사용할 기능·목표를 선택하고 회로 생성 단계로 진행합니다.</li><li><b>데이터시트</b> 버튼에서 부품 목록·핀·전원·설계 설명을 확인합니다.</li></ol><p>여기서 만드는 데이터시트는 <b>프로젝트의 시스템 요약</b>입니다. 제조사 원본 데이터시트와 구분합니다. 부품 후보·관측 정보·새로 선정한 값은 서로 다른 출처로 기록됩니다.</p>')+
 '<div class="status-row"><span><b>CONFIRMED</b> 검증된 정보</span><span><b>INFERRED</b> 추론한 정보</span><span><b>UNKNOWN</b> 확인하지 못한 원본 정보</span></div><p class="note">새 회로의 부품·핀·저항값은 선정할 수 있습니다. 그 선정값을 사진 속 원본의 확인된 사실로 표시하지 않습니다.</p>'))
sections.append(section(6,'editor','회로·코드와 3D 편집기','④ 회로·시뮬레이션에서 기존 아두이노 시스템 편집기를 엽니다.',
 '<div class="grid">'+card('회로·배선·구조물 보기','<ol><li>회로·보드·빵판과 각 핀에 연결된 배선을 확인합니다.</li><li><b>2D 보기</b>는 같은 3D 장면을 수직으로 내려다봅니다. 3D로 바꾸면 회전 제한을 해제합니다.</li><li><b>조립 / 분해 / 회로 보기</b>로 내부 부품을 확인합니다. 장착 부품과 배선 끝이 구조물의 움직임을 따라갑니다.</li><li>부품·구조물·배선을 클릭하면 작은 선택 카드가 나옵니다. 카드에서 이동을 활성화한 뒤 드래그합니다.</li></ol><p>선택하지 않은 상태에는 정보 카드를 띄우지 않습니다. 핀 위에서 빵판의 같은 전기적 연결선과 연결 부품을 확인하세요.</p>')+card('코드와 그래픽 조립 가이드','<p>코드 영역에서 생성된 소스·언어·보드 핀을 확인하고 편집합니다. 코드 번역 도구는 버튼으로 펼칩니다. 코드 전용 도구는 코드 영역, 회로 전용 도구는 회로 영역에 있습니다.</p><p>조립 가이드에서는 연결할 <b>양 끝을 한 단계</b>로 안내합니다. 단계 그래픽과 편집기 포인터를 함께 보고 연결하세요. 포인터는 부품을 덜 가리키도록 대각선으로 표시합니다.</p><p class="note">사진에서 만든 구조물은 기능·외형 확인용 근사 3D 오브젝트입니다. 숨겨진 내부나 실물 치수의 정밀 복원 결과가 아닙니다.</p>')+'</div>'))
sections.append(section(7,'simulation','실행하고 직접 조작하기','화면의 움직임, 보드 코드 실행, 전기 회로 계산의 검증 범위를 구분해 확인합니다.',
 card('▶ 실행 → 입력 조작 → 출력 확인','<ol><li>상단 <b>시뮬레이션</b> 카드에서 실행을 시작합니다.</li><li>컴파일이 끝나는지 확인하고 오류가 있으면 코드 영역의 오류를 봅니다.</li><li>버튼·가변저항·센서 입력 또는 해당 시스템의 컨트롤러를 조작합니다.</li><li>LED 밝기, LCD, 모터·서보, 급수 환경 등 설계에 연결된 출력을 확인합니다.</li><li>로봇은 화면에 안내된 키보드/컨트롤러를 사용하고 방향과 정지 동작을 검사합니다.</li></ol><p>UNO 경로는 로컬 AVR 컴파일과 AVR8js 실행을 사용합니다. 지원 회로는 ngspice로 전압·전류를 계산합니다. 파형은 Test Point(측정 지점)의 이름으로 비교합니다.</p>')+
 '<div class="table-wrap"><table><thead><tr><th>결과</th><th>확인하는 것</th><th>확인하지 못하는 것</th></tr></thead><tbody><tr><td>코드 실행</td><td>지원 보드의 컴파일·핀 출력·시간 변화</td><td>모든 외부 드라이버와 실제 전력 특성</td></tr><tr><td>전기 시뮬레이션</td><td>지원 소자 모델의 전압·전류·파형</td><td>실물 열·공차·모델에 없는 현상</td></tr><tr><td>기능·운동 미리보기</td><td>사용자 입력에 대한 가상 동작</td><td>드론의 실제 비행 안정성·로봇의 실제 접촉 물리</td></tr></tbody></table></div><p class="note">모든 사진이 자동으로 완벽한 실행 시스템으로 변환된다고 보장하지 않습니다. 지원하지 않는 실행기는 성공으로 표시하지 않습니다. 최종 조립·실물 동작은 사용자가 검증합니다.</p>'))
sections.append(section(8,'boards','시스템 전환과 지원 범위','편집기 상단 시스템 전환·파일 카드에서 대상 보드를 선택합니다.',
 card('주변 부품과 기능을 유지해 보드 변경','<p>변환은 기존 부품과 역할을 유지하면서 대상 보드의 전원·핀·전압 조건에 따라 <b>회로와 배선을 먼저</b> 구성합니다. 그다음 AI가 확정된 회로에 맞는 코드를 작성합니다. AI가 코드와 함께 하드웨어를 마음대로 바꾸는 경로가 아닙니다.</p><p>필요한 전압 보완 부품은 규칙으로 추가합니다. 전환 결과의 핀·전원·언어·실행 요구사항을 확인하세요. AI 코드 작성은 API 키와 크레딧이 필요합니다.</p>')+
 '<div class="table-wrap"><table><thead><tr><th>설계 프로필</th><th>코드</th><th>이 설치의 실행 범위</th></tr></thead><tbody><tr><td>Arduino UNO</td><td>Arduino C++</td><td>로컬 컴파일·실행 지원</td></tr><tr><td>ESP32</td><td>MicroPython</td><td>전용 실행 서비스 필요</td></tr><tr><td>Raspberry Pi Pico</td><td>MicroPython</td><td>전용 실행 서비스 필요</td></tr><tr><td>Raspberry Pi 4</td><td>Linux Python / GPIO</td><td>전용 실행 서비스 필요</td></tr></tbody></table></div><p>프로필이 등록돼 있다는 것은 그 보드의 실제 에뮬레이터가 이 설치에서 실행됐다는 뜻이 아닙니다. 최신 원본은 <a href="'+REPO+'/blob/main/data/board-profiles.json">board-profiles.json</a>입니다.</p>'))
sections.append(section(9,'save','저장·종료·업데이트','공개 소스와 개인 작업 데이터를 분리합니다.',
 '<div class="grid">'+card('작업 저장과 종료','<p>편집기의 파일·저장 도구에서 프로젝트를 저장하거나 <code>.vlx</code> 파일로 내려받습니다. 로컬 편집 내용은 브라우저 저장과 파일 저장을 구분하세요. SaaS 작업공간 저장은 별도 구성입니다.</p><p>업로드·분석 결과와 키는 기본 <code>.runtime/</code>에 남습니다. 종료하려면 실행한 터미널에서 <kbd>Ctrl+C</kbd>를 누릅니다. 종료는 저장 데이터를 삭제하지 않습니다.</p><p class="note">공개 저장소에는 사용자 사진·동영상·분석 기록·키·가상환경·설치된 의존성을 포함하지 않았습니다.</p>')+card('소스 업데이트',command('변경 여부 확인 후 업데이트','cd "$HOME/embedded-vision" && git status --short && git pull --ff-only','cmd-update')+'<p>코드 수정이 있으면 먼저 백업하거나 커밋하세요. 벤더 편집기 소스가 이미 설치된 경우 자동 초기화하지 않습니다. 새 편집기 패치 반영 절차는 README의 업데이트 설명을 따르세요.</p>')+'</div>'))
sections.append(section(10,'trouble','문제가 생기면','API 호출 없이 설치·서버·예제를 먼저 구분해 확인합니다.',
 card('서버 상태와 로그',command('두 서버 상태 확인','curl -fsS http://127.0.0.1:8766/api/health && printf "\\n" && curl -fsS http://127.0.0.1:8768/api/health','cmd-health')+command('로컬 로그 확인','cd "$HOME/embedded-vision" && tail -n 60 .runtime/launcher/analysis.log .runtime/launcher/editor.log','cmd-logs')+'<p>로그를 공유하기 전에 개인 경로·입력 정보를 확인하세요. API 키는 공유하지 마세요.</p>')+
 '<div class="grid">'+card('포트가 사용 중입니다', '<p>실행기는 기존 서버를 강제로 종료하지 않습니다. 먼저 자신이 실행한 서버를 종료하거나 다른 포트를 지정하세요. 두 포트는 서로 달라야 합니다.</p>'+command('다른 포트로 실행','cd "$HOME/embedded-vision" && EMBEDDED_VISION_PORT=8866 EMBEDDED_VISION_EDITOR_PORT=8868 bash start.sh','cmd-ports'))+card('컴파일·설치 실패','<p><b>bwrap 오류:</b> 운영체제의 격리 실행 설정을 확인하세요. 설치기는 컴파일 격리를 끄지 않습니다.</p><p><b>다른 운영체제:</b> 현재 자동 설치는 Ubuntu 22.04 x86_64 전용입니다. Windows/macOS/ARM/다른 Ubuntu 버전은 검증하지 않았습니다.</p><p><b>다운로드·빌드 오류:</b> 인터넷·디스크 여유·패키지 오류를 확인하고 같은 명령을 다시 실행하세요. 이미 완료한 설치 단계는 재사용합니다.</p>')+'</div>'))
sections.append(section(11,'architecture','개발 구조와 검증 범위','지금까지 만든 모듈·데이터·편집기 패치를 공개 소스에 함께 보관합니다.',
 '<div class="grid">'+card('입력에서 실행까지','<ol><li><code>backend/vision</code> · 프레임/OCR/확대·관측</li><li><code>backend/planner</code> · 모델 선택·JSON 응답·도구 실행 제한</li><li><code>backend/design</code> · 부품 목록·기능·회로·구조 설계</li><li><code>backend/circuit</code> · Circuit Graph(회로의 공통 데이터)</li><li><code>backend/workbench</code> · 편집기 변환·격리 UNO 컴파일</li><li><code>frontend</code> · 사진 입력·단계·데이터시트</li><li><code>patches</code> · Velxio 기반 2D/3D 편집기 수정</li><li><code>data</code> · 보드·부품·예제·공통 워크플로우</li></ol>')+card('포함한 것과 다음 검증','<p>사진/영상 워크플로우, 부품 확대 재검토, 기능 보완, 시스템 데이터시트, 회로·코드·배선, 3D 구조·분해·장착, 조립 가이드, 보드 전환, 지원 시뮬레이션, SaaS 기초 코드와 자동 테스트가 포함됩니다.</p><p>KiCad/PCB 모듈은 선택 사항입니다. 기본 설치의 목적은 웹 편집기·시뮬레이터 실행입니다. 이번 설치 검증과 유료 AI 인식 정확도·실물 검증은 서로 다릅니다.</p><p>세부 설계는 <a href="'+REPO+'/blob/main/docs/common-workflow.md">공통 워크플로우</a>, 라이선스는 <a href="'+REPO+'/blob/main/THIRD_PARTY_NOTICES.md">출처·라이선스</a>에서 확인하세요. 과거 문서의 <code>outputs/</code> 기록은 개인 분석 자료이므로 공개 저장소에 없습니다.</p>')+'</div>'))

css='''
:root{--ground:#f1f2ee;--surface:#fff;--surface2:#e8eae3;--ink:#16191c;--muted:#49535e;--rule:#d9ddd3;--accent:#0b6ca8;--warm:#b8480f;--code:#14212a;--codeink:#e6f1f8;color-scheme:light}
[data-theme=dark]{--ground:#12191e;--surface:#1b252c;--surface2:#25323b;--ink:#edf2f5;--muted:#b5c4cc;--rule:#3b4b55;--accent:#76caff;--warm:#ffb18a;color-scheme:dark}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:32px}body{margin:0;background:var(--ground);color:var(--ink);font:16px/1.8 system-ui,-apple-system,"Noto Sans KR",sans-serif}a{color:var(--accent);text-underline-offset:4px}button,.link-button{font:inherit;font-size:14px;min-height:44px;border:1px solid var(--rule);border-radius:8px;padding:8px 15px;background:var(--surface);color:var(--ink);cursor:pointer;white-space:normal}button:hover,.link-button:hover{border-color:var(--accent);color:var(--accent)}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.wrap{max-width:1280px;margin:auto;padding:32px 32px 90px}.masthead{display:flex;justify-content:space-between;align-items:center;gap:20px;border-bottom:1px solid var(--rule);padding-bottom:18px}.eyebrow{font:600 12px/1.5 ui-monospace,monospace;letter-spacing:.13em;color:var(--muted)}.top h1{font-size:clamp(34px,5vw,64px);line-height:1.25;letter-spacing:-.06em;max-width:1000px;margin:35px 0 22px}.standfirst{font-size:20px;max-width:840px;color:var(--muted)}.meta{display:flex;gap:10px;flex-wrap:wrap;margin:25px 0}.meta span,.badge{font-size:12px;border:1px solid var(--rule);padding:4px 9px;border-radius:5px;color:var(--muted)}.hero{display:grid;grid-template-columns:1.3fr 1fr;gap:28px;background:var(--surface);border:1px solid var(--rule);border-top:4px solid var(--accent);padding:28px;margin:30px 0}.hero h2{font-size:24px;margin-top:0}.hero p{color:var(--muted)}.hero nav{display:grid;grid-template-columns:1fr 1fr;gap:4px 16px}.hero nav a{display:block;padding:8px 0;font-size:14px}.flow{display:flex;flex-wrap:wrap;gap:10px;padding:0;list-style:none;margin:28px 0 50px}.flow li{flex:1;min-width:135px;background:var(--surface2);padding:15px;border-left:3px solid var(--accent);font-size:14px}.flow b{display:block;color:var(--accent);font:700 24px/1.4 ui-monospace,monospace}.sec-head{display:flex;gap:20px;align-items:baseline;border-top:2px solid var(--ink);padding-top:18px;margin-top:58px}.sec-num{font:600 20px/1.4 ui-monospace,monospace;color:var(--accent)}h2{font-size:27px;line-height:1.4;margin:0}h3{font-size:18px;line-height:1.5;margin:0}.section-intro{color:var(--muted);max-width:900px;margin:14px 0 24px}.spec{background:var(--surface);border:1px solid var(--rule);border-radius:10px;overflow:hidden;margin:16px 0}.spec-head{display:flex;justify-content:space-between;gap:14px;align-items:center;padding:18px 22px;border-bottom:1px solid var(--rule)}.spec-body{padding:8px 22px 20px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:start}.grid .spec{height:calc(100% - 32px)}p{overflow-wrap:anywhere}.note{font-size:14px;color:var(--muted);border-left:3px solid var(--warm);padding-left:14px}li{padding:5px 0}code,kbd{font-family:ui-monospace,"DejaVu Sans Mono",monospace;font-size:.88em}p code,li code{background:var(--surface2);padding:2px 5px;border-radius:3px;overflow-wrap:anywhere}kbd{border:1px solid var(--rule);padding:2px 6px;border-radius:4px}.command{border:1px solid var(--rule);border-radius:8px;margin:18px 0;overflow:hidden}.command-head{padding:12px 14px;background:var(--surface2);display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}.command-head b{font-size:14px}.command-actions{display:flex;gap:7px;flex-wrap:wrap}.command pre{margin:0;background:var(--code);color:var(--codeink);padding:20px;white-space:pre-wrap;word-break:break-all;font-size:14px;line-height:1.8}.command [hidden]{display:none}details{margin:15px 0;border-top:1px solid var(--rule);padding-top:12px}summary{cursor:pointer;min-height:44px;display:list-item;color:var(--accent);font-size:14px}.preview{display:flex;align-items:center;justify-content:space-evenly;gap:15px;padding:30px 20px;border:1px solid var(--rule);background:var(--surface);border-radius:10px;margin:24px 0}.preview-board{background:#087b8e;color:white;padding:24px;border-radius:12px;font-weight:700}.pins{font:13px ui-monospace,monospace;margin-top:20px;border-top:4px dashed #dfd8aa;padding-top:10px}.preview-part,.preview-result{text-align:center;padding:15px;background:var(--surface2);border-radius:10px}small{font-size:13px;color:var(--muted)}.wire{font-size:28px;color:var(--warm)}.status-row{display:flex;flex-wrap:wrap;gap:12px}.status-row span{flex:1;background:var(--surface);border:1px solid var(--rule);border-radius:8px;padding:16px;font-size:14px}.status-row b{display:block;color:var(--accent);font:600 13px/2 ui-monospace,monospace}.table-wrap{overflow-x:auto;background:var(--surface);border:1px solid var(--rule);border-radius:9px;margin:20px 0}table{width:100%;border-collapse:collapse;min-width:530px;font-size:14px}th,td{text-align:left;vertical-align:top;padding:15px;border-bottom:1px solid var(--rule)}th{background:var(--surface2)}footer{margin-top:65px;border-top:1px solid var(--rule);padding-top:24px;color:var(--muted);font-size:14px}.toast{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);background:var(--ink);color:var(--surface);padding:12px 20px;border-radius:8px;z-index:10;max-width:90vw}.toast:empty{display:none}.link-button{display:inline-flex;align-items:center;text-decoration:none;gap:5px}.actions{display:flex;gap:8px;flex-wrap:wrap}.skip{position:absolute;top:-80px}.skip:focus{top:8px;background:var(--surface);padding:10px;z-index:20}
@media(max-width:800px){.wrap{padding:20px 18px 60px}.hero,.grid{grid-template-columns:1fr}.hero{padding:20px}.grid{gap:0}.grid .spec{height:auto}.spec-head,.spec-body{padding-left:17px;padding-right:17px}.preview{flex-wrap:wrap}.flow li{min-width:120px}.top h1{font-size:38px}.standfirst{font-size:17px}.masthead{align-items:flex-start}.sec-head{gap:12px}h2{font-size:24px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
'''
js='''
const toast=document.querySelector('[role=status]');let timer;
function notify(message){toast.textContent=message;clearTimeout(timer);timer=setTimeout(()=>toast.textContent='',2500)}
async function copyText(text){if(navigator.clipboard&&window.isSecureContext){try{await navigator.clipboard.writeText(text);return}catch{}}const field=document.createElement('textarea');field.value=text;field.style.cssText='position:fixed;opacity:0;left:0;top:0';document.body.append(field);field.select();const ok=document.execCommand('copy');field.remove();if(!ok)throw Error('copy failed')}
document.addEventListener('click',async event=>{const button=event.target.closest('button[data-action]');if(!button)return;const action=button.dataset.action;if(action==='reveal'){const block=document.getElementById(button.getAttribute('aria-controls'));block.hidden=!block.hidden;button.setAttribute('aria-expanded',String(!block.hidden));button.textContent=block.hidden?'명령어 보기':'명령어 접기'}if(action==='copy'){try{await copyText(document.getElementById(button.dataset.source).textContent);notify('명령어를 복사했습니다. 터미널에 붙여넣으세요.')}catch{notify('복사 권한을 확인하거나 명령어 보기에서 직접 복사하세요.')}}if(action==='theme'){const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;button.setAttribute('aria-pressed',String(theme==='dark'));try{localStorage.setItem('ev-tutorial-theme',theme)}catch{}}});
try{const theme=localStorage.getItem('ev-tutorial-theme');if(theme==='dark'){document.documentElement.dataset.theme=theme;document.querySelector('[data-action=theme]').setAttribute('aria-pressed','true')}}catch{}
'''
nav=''.join(f'<a href="#{ident}">{label}</a>' for ident,label in [('start','01 설치·실행'),('sample','02 예제 실행'),('key','03 API 키'),('input','04 사진·영상'),('design','05 기능·데이터시트'),('editor','06 회로·3D 편집'),('simulation','07 시뮬레이션'),('boards','08 시스템 전환'),('save','09 저장·종료'),('trouble','10 문제 해결'),('architecture','11 개발 구조')])
html=f'''<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Embedded Vision 설치부터 사진 분석, 회로·3D 편집, 아두이노 시뮬레이션까지 단계별 튜토리얼"><title>Embedded Vision — 설치·실행 튜토리얼</title><style>{css}</style></head><body><a class="skip" href="#start">설치 단계로 바로 가기</a><main class="wrap"><header class="top"><div class="masthead"><div class="eyebrow">EMBEDDED VISION / FIELD GUIDE 01<br>PHOTO → CIRCUIT → INTERACTIVE SIMULATION</div><button data-action="theme" aria-pressed="false">밝게 / 어둡게</button></div><h1>사진에서 회로로,<br>직접 움직이는 시스템까지.</h1><p class="standfirst">지금까지 만든 사진 분석·회로 설계·3D 편집·시뮬레이션을 내 컴퓨터에서 실행하는 단계별 가이드입니다. 명령어를 보고 복사한 뒤 터미널에 붙여넣으세요.</p><div class="meta"><span>Ubuntu 22.04 · x86_64</span><span>예제는 API 키 없이 실행</span><span>사진 AI 분석은 별도 API 필요</span><span>2026.11.12 · 공개 소스판</span></div></header><div class="hero"><div><h2>먼저 예제로 확인하세요.</h2><p>한 명령으로 설치하고 화면을 연 다음, 내장 아두이노 예제를 실행합니다. 이후 API 키를 연결해 직접 찍은 사진을 분석하세요.</p><div class="actions"><a class="link-button" href="#start">설치 시작 ↓</a><a class="link-button" href="{REPO}">GitHub 소스 ↗</a><a class="link-button" href="http://127.0.0.1:8766/">로컬 화면 열기 ↗</a></div></div><nav aria-label="튜토리얼 목차">{nav}</nav></div><ol class="flow" aria-label="전체 흐름"><li><b>01</b>설치·예제 실행</li><li><b>02</b>사진·부품 확인</li><li><b>03</b>기능·회로 생성</li><li><b>04</b>3D 편집·가이드</li><li><b>05</b>조작·출력 검증</li></ol>{''.join(sections)}<footer><p>이 HTML은 서버 없이 파일로 열어도 목차·테마·명령어 보기·복사가 동작합니다. 명령어 버튼은 복사만 하며 컴퓨터에서 자동 실행하지 않습니다. 복사한 명령은 사용자가 터미널에서 실행합니다.</p><p><a href="{REPO}">PGH-snfl / embedded-vision</a> · AGPL-3.0 · <a href="{REPO}/blob/main/THIRD_PARTY_NOTICES.md">오픈소스·사진 출처</a><br>같은 폴더의 드론 튜토리얼처럼 단계별 카드와 명령어 복사 방식으로 구성했습니다.</p></footer></main><div class="toast" role="status" aria-live="polite"></div><script>{js}</script></body></html>'''
(ROOT/'tutorial.html').write_text(html,encoding='utf-8')
(ROOT/'docs/index.html').write_text(html,encoding='utf-8')
(ROOT/'frontend/tutorial.html').write_text(html.replace(f'<style>{css}</style>', '<link rel="stylesheet" href="/tutorial.css">').replace(f'<script>{js}</script>', '<script src="/tutorial.js"></script>'),encoding='utf-8')
(ROOT/'frontend/tutorial.css').write_text(css,encoding='utf-8')
(ROOT/'frontend/tutorial.js').write_text(js,encoding='utf-8')
print('Generated tutorial.html')
